#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=5

RUNTIME_ENV="${RUNTIME_ENV:-/etc/ordivon/ordivon-runtime.env}"
LEGACY_ROOT="${LEGACY_ROOT:-/root/.config/ordivon/secrets}"
CREDENTIAL_ROOT_BASE="${CREDENTIAL_ROOT_BASE:-/var/lib/ordivon/credentials}"
RUNTIME_SERVICE="${RUNTIME_SERVICE:-ordivon-runtime.service}"
PLAN_FILE="${PLAN_FILE:-/run/ordivon-model-provider-credential-plan.json}"
BACKUP_TAG="$(date -u +%Y%m%dT%H%M%SZ)"

require_cmd() {
  command -v "$1" >/dev/null 2>&1 || {
    printf 'missing required command: %s\n' "$1" >&2
    exit 1
  }
}

extract_api_key() {
  local source="$1"
  python3 - "$source" <<'PY'
import json, stat, sys
from pathlib import Path
p = Path(sys.argv[1])
if p.is_symlink() or not p.is_file():
    raise SystemExit("legacy carrier must be a regular non-symlink file")
mode = stat.S_IMODE(p.stat().st_mode)
if mode != 0o600:
    raise SystemExit(f"legacy carrier mode must be 0600, got {oct(mode)}")
obj = json.loads(p.read_text())
value = obj.get("apiKey")
if not isinstance(value, str) or not value or value != value.strip():
    raise SystemExit("legacy carrier apiKey is missing or invalid")
sys.stdout.write(value)
PY
}

plan_authorities() {
  python3 - "$RUNTIME_ENV" "$CREDENTIAL_ROOT_BASE" "$PLAN_FILE" <<'PY'
import json, os, sys
from pathlib import Path

env_path = Path(sys.argv[1])
root_base = Path(sys.argv[2])
plan_path = Path(sys.argv[3])
if env_path.is_symlink() or not env_path.is_file():
    raise SystemExit("Runtime environment file must be a regular non-symlink file")

raw = None
for line in env_path.read_text().splitlines():
    if line.startswith("ORDIVON_CREDENTIAL_AUTHORITIES_JSON="):
        raw = line.split("=", 1)[1].strip()
        break
if raw is None:
    raise SystemExit("ORDIVON_CREDENTIAL_AUTHORITIES_JSON is absent")
if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
    raw = raw[1:-1]
authorities = json.loads(raw)
if not isinstance(authorities, list):
    raise SystemExit("CredentialAuthority config is not an array")
by_name = {item.get("name"): item for item in authorities if isinstance(item, dict)}
anchor = by_name.get("openrouter-provider")
if not isinstance(anchor, dict):
    raise SystemExit("openrouter-provider authority is required as the principal ACL anchor")
allowed = anchor.get("allowedPrincipals")
if not isinstance(allowed, list) or not allowed or not all(isinstance(x, str) and x for x in allowed):
    raise SystemExit("openrouter-provider allowedPrincipals is missing/invalid")

names = [
    "openrouter-provider",
    "deepseek-provider",
    "google-provider",
    "cerebras-provider",
    "nvidia-provider",
    "bigmodel-provider",
]
roots = {}
for name in names:
    existing = by_name.get(name)
    if isinstance(existing, dict) and isinstance(existing.get("root"), str) and existing["root"]:
        roots[name] = existing["root"]
    else:
        roots[name] = str(root_base / name)

plan = {
    "schemaVersion": 1,
    "kind": "ordivon.model-provider-credential-migration-plan",
    "runtimeEnvironment": str(env_path),
    "allowedPrincipals": allowed,
    "roots": roots,
}
plan_path.parent.mkdir(parents=True, exist_ok=True)
plan_path.write_text(json.dumps(plan, sort_keys=True, separators=(",", ":")))
os.chmod(plan_path, 0o600)
PY
}

authority_root() {
  python3 - "$PLAN_FILE" "$1" <<'PY'
import json, sys
obj=json.load(open(sys.argv[1]))
print(obj["roots"][sys.argv[2]])
PY
}

encrypt_carrier() {
  local source_name="$1" authority="$2" credential="$3"
  local source="$LEGACY_ROOT/$source_name"
  local root target temp backup
  root="$(authority_root "$authority")"
  target="$root/$credential"
  install -d -m 0700 "$root"
  if [[ -e "$target" ]]; then
    backup="$target.bak-$BACKUP_TAG"
    cp -a -- "$target" "$backup"
  fi
  temp="$root/.${credential}.tmp-$$"
  rm -f -- "$temp"
  umask 077
  if ! extract_api_key "$source" | systemd-creds encrypt \
      --with-key=host --name="$credential" - "$temp" >/dev/null; then
    rm -f -- "$temp"
    printf 'failed encrypting %s -> %s/%s\n' "$source_name" "$authority" "$credential" >&2
    exit 1
  fi
  chmod 0600 "$temp"
  mv -f -- "$temp" "$target"
  printf '  %s✓ encrypted%s %s → %s/%s\n' "$GREEN" "$RESET" "$source_name" "$authority" "$credential"
}

merge_runtime_authorities() {
  python3 - "$RUNTIME_ENV" "$PLAN_FILE" "$BACKUP_TAG" <<'PY'
import json, os, shutil, stat, sys
from pathlib import Path

env_path = Path(sys.argv[1])
plan = json.load(open(sys.argv[2]))
tag = sys.argv[3]
lines = env_path.read_text().splitlines()
index = next((i for i,line in enumerate(lines) if line.startswith("ORDIVON_CREDENTIAL_AUTHORITIES_JSON=")), None)
if index is None:
    raise SystemExit("CredentialAuthority environment line disappeared")
raw = lines[index].split("=",1)[1].strip()
quote = ""
if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
    quote = raw[0]
    raw = raw[1:-1]
authorities = json.loads(raw)
by_name = {item.get("name"): item for item in authorities if isinstance(item, dict)}
allowed = plan["allowedPrincipals"]

for name, root in plan["roots"].items():
    existing = by_name.get(name)
    item = {"name": name, "root": root, "allowedPrincipals": allowed}
    if isinstance(existing, dict):
        existing.clear()
        existing.update(item)
    else:
        authorities.append(item)
        by_name[name] = item

encoded = json.dumps(authorities, separators=(",", ":"))
lines[index] = "ORDIVON_CREDENTIAL_AUTHORITIES_JSON=" + (quote + encoded + quote if quote else encoded)

backup = env_path.with_name(env_path.name + ".bak-model-provider-" + tag)
shutil.copy2(env_path, backup)
st = env_path.stat()
tmp = env_path.with_name(env_path.name + ".tmp-model-provider")
tmp.write_text("\n".join(lines) + "\n")
os.chmod(tmp, stat.S_IMODE(st.st_mode))
os.chown(tmp, st.st_uid, st.st_gid)
os.replace(tmp, env_path)
print(str(backup))
PY
}

banner "Ordivon model-provider credential migration"

stage "Preflight"
say "This migrates existing local API carriers into systemd-encrypted Runtime CredentialAuthorities."
say "No API key is printed, written to the Runtime env file, or committed to Git."
if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
  warn "This operator migration must run as root so it can write /var/lib/ordivon/credentials and /etc/ordivon."
  exit 1
fi
for cmd in python3 systemd-creds systemctl install stat; do require_cmd "$cmd"; done
[[ -f "$RUNTIME_ENV" && ! -L "$RUNTIME_ENV" ]] || { warn "Runtime environment file unavailable: $RUNTIME_ENV"; exit 1; }
plan_authorities
say "Credential authorities to realize:"
python3 - "$PLAN_FILE" <<'PY'
import json, sys
p=json.load(open(sys.argv[1]))
for name, root in p["roots"].items():
    print(f"  - {name}: {root}")
print("  - allowedPrincipals are inherited from the existing openrouter-provider authority")
PY
pause "Review the non-secret plan above, then press Enter."

stage "Encrypt legacy carriers"
say "Each existing 0600 JSON carrier is streamed directly into systemd-creds encrypt."
confirm "Encrypt/rotate the model-provider CredentialAuthority blobs now?" || exit 1
encrypt_carrier "openrouter.json" "openrouter-provider" "api_key"
encrypt_carrier "deepseek.json"  "deepseek-provider" "api_key_0"
encrypt_carrier "deepseek1.json" "deepseek-provider" "api_key_1"
encrypt_carrier "deepseek2.json" "deepseek-provider" "api_key_2"
encrypt_carrier "deepseek3.json" "deepseek-provider" "api_key_3"
encrypt_carrier "deepseek4.json" "deepseek-provider" "api_key_4"
encrypt_carrier "deepseek5.json" "deepseek-provider" "api_key_5"
encrypt_carrier "google.json"  "google-provider" "api_key_0"
encrypt_carrier "google1.json" "google-provider" "api_key_1"
encrypt_carrier "google2.json" "google-provider" "api_key_2"
encrypt_carrier "google3.json" "google-provider" "api_key_3"
encrypt_carrier "google4.json" "google-provider" "api_key_4"
encrypt_carrier "cerebras.json" "cerebras-provider" "api_key"
encrypt_carrier "nvidia.json" "nvidia-provider" "api_key"
encrypt_carrier "bigmodel.json" "bigmodel-provider" "api_key"

stage "Bind Runtime authorities"
say "The existing CredentialAuthority array will be preserved and the six model-provider authorities merged into it."
confirm "Atomically update $RUNTIME_ENV?" || exit 1
ENV_BACKUP="$(merge_runtime_authorities)"
say "Runtime env backup: $ENV_BACKUP"
say "No plaintext credential was placed in the environment file."

stage "Restart Runtime"
warn "This is the only service restart in the migration."
confirm "Restart $RUNTIME_SERVICE so the new CredentialAuthorities become visible?" || exit 1
systemctl restart "$RUNTIME_SERVICE"
if ! systemctl is-active --quiet "$RUNTIME_SERVICE"; then
  warn "$RUNTIME_SERVICE did not become active. Runtime env backup is $ENV_BACKUP"
  exit 1
fi
say "$RUNTIME_SERVICE is active."

stage "Handoff"
say "Encrypted credential provisioning is complete."
say "Do not decrypt or paste any API key into chat."
say "Return to ChatGPT; it will verify runtime.describe, run provider-native read-only probes,"
say "sync AUTH-PASS credentials into CC Switch through workspace.execCredentialBoundTrusted,"
say "and qualify Harness routes without exposing secret bytes."
rm -f -- "$PLAN_FILE"

finish
